export function clamp(x: number, lo: number, hi: number, inclusive: boolean = true): number {
  if (inclusive) {
    return Math.min(Math.max(x, lo), hi);
  }

  if (x <= lo) {
    return lo + Number.EPSILON;
  }

  if (x >= hi) {
    return hi - Number.EPSILON;
  }

  return x;
}

export function clamp(x: number, lo: number, hi: number): string {
  const bounded = Math.min(Math.max(x, lo), hi);
  return String(bounded);
}

export function clampValue(x: number, lo: number, hi: number): number {
  return Math.min(Math.max(x, lo), hi);
}
